using Azure.Identity;
using Azure.Security.KeyVault.Secrets;

var kvUri = new Uri("https://my-vault.vault.azure.net/");
var client = new SecretClient(kvUri, new DefaultAzureCredential());

KeyVaultSecret secret = await client.GetSecretAsync("database-password");
Console.WriteLine(`Database password retrieved: {secret.Value}`);

